CREATE FUNCTION audit_test.track_view(p_workspace uuid,p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE actor audit_test.members; BEGIN IF p_action NOT IN ('Cases viewed','Activity viewed') THEN RAISE EXCEPTION 'Unknown read operation'; END IF; SELECT * INTO actor FROM audit_test.members WHERE workspace_id=p_workspace AND user_id=(SELECT auth.uid()) AND active; IF NOT FOUND THEN RETURN; END IF; INSERT INTO audit_test.activity(workspace_id,subject_id,action,actor_id,actor_name,actor_email) VALUES(p_workspace,p_workspace,p_action,actor.user_id,actor.display_name,actor.email); END $$; REVOKE ALL ON FUNCTION audit_test.track_view(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION audit_test.track_view(uuid,text) TO authenticated; CREATE OR REPLACE FUNCTION public.audit_test_list_cases(p_workspace uuid,p_before timestamptz DEFAULT 'infinity',p_before_id uuid DEFAULT 'ffffffff-ffff-ffff-ffff-ffffffffffff',p_limit integer DEFAULT 50) RETURNS SETOF audit_test.cases LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path='' AS $$ BEGIN PERFORM audit_test.track_view(p_workspace,'Cases viewed'); RETURN QUERY SELECT c.* FROM audit_test.cases c WHERE workspace_id=p_workspace AND (updated_at,id)<(p_before,p_before_id) ORDER BY updated_at DESC,id DESC LIMIT greatest(1,least(coalesce(p_limit,50),100)); END $$; CREATE OR REPLACE FUNCTION public.audit_test_activity(p_workspace uuid,p_before bigint DEFAULT 9223372036854775807,p_limit integer DEFAULT 100) RETURNS SETOF audit_test.activity LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path='' AS $$ BEGIN PERFORM audit_test.track_view(p_workspace,'Activity viewed'); RETURN QUERY SELECT a.* FROM audit_test.activity a WHERE workspace_id=p_workspace AND seq<p_before ORDER BY seq DESC LIMIT greatest(1,least(coalesce(p_limit,100),100)); END $$; CREATE POLICY audit_test_storage_anon_boundary ON storage.objects AS RESTRICTIVE FOR ALL TO anon USING(bucket_id<>'audit-test-evidence') WITH CHECK(bucket_id<>'audit-test-evidence');
